#include <bits/stdc++.h>
using namespace std;
#define ll long long
const int MOD=998244353;
int main() {
   ios::sync_with_stdio(false);
   cin.tie(nullptr);
   int tc;
   cin>>tc;
   while(tc--){
       int n;
       cin>>n;
       vector<int>value(n+1);
       vector<vector<int>>pos(n+1);
       for(int i=1;i<=n;i++){
           cin>>value[i];
           pos[value[i]].push_back(i);
       }
       vector<long long>ways(1,1);
       for(int x=1;x<=n;x++){
           vector<long long>next(x+1);
           int options=(x==n?1:2);
           for(int left=0;left<x;left++){
               if(!ways[left]) continue;
               int right=x-1-left;
               int leftEnd=left+1;
               int rightEnd=n-right;
               for(int side=0;side<options;++side){
                   int placedAt=(side==0?leftEnd:rightEnd);
                   bool good=true;
                   for(int idx:pos[x]){
                       int before=min(idx,leftEnd-1)+max(0,idx-rightEnd);
                       int needPrefix=(idx-1)/2;
                       bool prefix=placedAt<=idx&&before==needPrefix;
                       int after=max(0,leftEnd-idx)+min(n-idx+1,n-rightEnd);
                       int needSuffix=(n-idx)/2;
                       bool suffix= placedAt>=idx&&after==needSuffix;
                       if(!prefix&&!suffix){
                           good=false;
                           break;
                       }
                       
                   }
                   if(!good) continue;
                   int nl=left+(side==0);
                   next[nl]+=ways[left];
                   if(next[nl]>=MOD) next[nl]-=MOD;
               }
           }
           ways.swap(next);
       }
       long long answer=0;
       for(long long x:ways){
           answer+=x;
           if(answer>=MOD) answer-=MOD;
       }
       cout<<answer<<"\n";
   }
   return 0;

}
